text:
{
  "title": "سياسة الخصوصية وشروط الاستخدام لخدمات شركة الروافد الرقمية",
  "planted": [
    {
      "slot": "p1",
      "text": "يفترض النظام بخصوص القنوات الشخصية أن استخدام المنصة يشكل تفويضاً ضمنياً لتلقي العروض الترويجية والإشعارات الإعلانية من الشركة والجهات المرتبطة بها، مع توفير خيارات إعدادات الحساب التي تتيح للمستخدم تحديث تفضيلات الاتصال بحسب ما ترتاه الإدارة ملائماً."
    },
    {
      "slot": "p2",
      "text": "تحتفظ الشركة بحق الاستفادة من كافة المعلومات والبيانات التي يتم جمعها خلال استخدام الخدمة لأغراض تطوير الأعمال، وتحسين جودة التجربة، وتلبية المتطلبات التشغيلية المستقبلية التي قد تظهر تباعاً دون الحاجة لإشعار مسبق."
    },
    {
      "slot": "p3",
      "text": "يعتبر استمرار العميل في تصفح المنصة أو الاستفادة من مزاياها بمثابة موافقة تامة ونهائية على آليات معالجة البيانات المعتمدة، ولا تقبل طلبات سحب هذه الموافقة طالما كان الحساب نشطاً وقائماً."
    },
    {
      "slot": "p4",
      "text": "تلتزم المنصة بعرض البنود الأساسية لسياسة التعامل مع المعلومات قبل إتمام عملية التسجيل، والتي توضح طبيعة البيانات المطلوبة وأساليب حفظها ومعالجتها وكيفية التواصل مع فريق الدعم."
    },
    {
      "slot": "p5",
      "text": "يحق للمستفيد مراجعة سجلاته المعالجة وطلب تعديل أو تصحيح ما يظهر له من معلومات غير دقيقة، إضافة إلى طلب إزالة البيانات التي انتهت الحاجة التشغيلية الفورية لها، وفقاً للضوابط الداخلية للشركة."
    },
    {
      "slot": "p6",
      "text": "في حال وقوع أي حادثة تقنية تؤثر على سلامة الأنظمة أو البيانات، تتخذ الشركة الإجراءات اللازمة للتعامل مع الموقف وإبلاغ الجهات المعنية وذوي الشأن وفقاً لما تقدره الإدارة وحسب ما تقتضيه الظروف الفنية للواقعة."
    }
  ],
  "neutral": [
    "تخضع كافة المعاملات المالية ورسوم الاشتراك الموضحة في قائمة الأسعار للضرائب والرسوم الحكومية السارية وقت إصدار الفاتورة.",
    "تتم عمليات سداد المستحقات المالية عبر قنوات الدفع الإلكترونية المعتمدة لدى المنصة، ولا تتحمل الشركة مسؤولية أي تأخير ناتج عن الأنظمة البنكية للعميل.",
    "تبدأ مدة الاتفاقية من تاريخ تفعيل الحساب وتستمر تجدداً تلقائياً ما لم يقم أحد الطرفين بتقديم طلب إنهاء وفق الآليات المحددة.",
    "لا تتحمل الشركة أي مسؤولية قانونية عن الأضرار غير المباشرة أو خسارة الأرباح الناتجة عن انقطاع المؤقت للخدمة لأسباب خارجة عن إرادتها.",
    "تخضع هذه الشروط والأحكام وتفسر وفقاً للأنظمة المعمول بها في المملكة العربية السعودية، وتختص الجهات القضائية بالفصل في أي نزاع ينشأ عنها.",
    "يقصد بالكلمات والعبارات الواردة في هذه الشروط المعاني المعتادة لها في السياق التجاري والتقني ما لم يقتضِ السياق خلاف ذلك.",
    "تعتبر كافة حقوق الملكية الفكرية، والعلامات التجارية، والتصاميم، والنصوص الخاصة بالمنصة ملكية خالصة للشركة، ولا يحق لأي طرف استخدامها دون إذن خطي مسبق.",
    "تتم عملية تقديم الخدمات الرقمية فور اكتمال خطوات التسجيل وسداد الرسوم، وتعتبر الخدمة قد سلمت للمستفيد بمجرد إتاحة الوصول إليها عبر حسابه."
  ]
}
